import asyncio, sys
from playwright.async_api import async_playwright

URL = "file:///tmp/accept-landing-page-parallel-v1-v0-1-1glnaih7/x03/landing.html"
OUT = "/tmp/accept-landing-page-parallel-v1-v0-1-1glnaih7/x03/"

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        for name, w, h in [("mobile", 375, 667), ("desktop", 1280, 800)]:
            ctx = await browser.new_context(viewport={"width": w, "height": h})
            page = await ctx.new_page()
            errors = []
            page.on("pageerror", lambda e: errors.append(str(e)))
            page.on("requestfailed", lambda r: errors.append("REQFAIL " + r.url))
            await page.goto(URL, wait_until="load")
            # block external network then reload to verify offline rendering
            await page.route("**/*", lambda route: asyncio.ensure_future(
                route.abort()) if route.request.url.startswith("http") else asyncio.ensure_future(route.continue_()))
            await page.reload(wait_until="load")
            hscroll = await page.evaluate("document.documentElement.scrollWidth > document.documentElement.clientWidth")
            await page.screenshot(path=OUT + f"shot_{name}_top.png")
            await page.screenshot(path=OUT + f"shot_{name}_full.png", full_page=True)
            # geometry checks
            geo = await page.evaluate("""() => {
                const r = s => { const e = document.querySelector(s); if(!e) return null;
                    const b = e.getBoundingClientRect(); return {t:b.top,b:b.bottom,l:b.left,r:b.right}; };
                const m = document.querySelector('main').getBoundingClientRect();
                return { brand: r('.brand'), lastPrice: r('.cards .card:last-child .price'),
                         cta: r('.cta'), mainW: m.width, mainL: m.left, mainR: m.right,
                         vw: document.documentElement.clientWidth };
            }""")
            print(name, "hscroll:", hscroll, "errors:", errors)
            print(name, "geo:", geo)
            await ctx.close()
        await browser.close()

asyncio.run(main())


