import asyncio, pathlib
from playwright.async_api import async_playwright

HTML = pathlib.Path("landing.html").resolve().absolute().as_uri()

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        for name, w, h in [("mobile", 320, 568), ("desktop", 1024, 768)]:
            ctx = await browser.new_context(viewport={"width": w, "height": h})
            page = await ctx.new_page()
            errors = []
            page.on("pageerror", lambda e: errors.append(str(e)))
            page.on("requestfailed", lambda r: errors.append("REQFAIL " + r.url))
            await page.route("**/*", lambda route: route.abort() if route.request.url != HTML else route.continue_())
            await page.goto(HTML)
            await page.screenshot(path=f"shot_{name}_top.png")
            await page.screenshot(path=f"shot_{name}_full.png", full_page=True)
            hscroll = await page.evaluate("document.documentElement.scrollWidth > document.documentElement.clientWidth")
            print(name, "hscroll:", hscroll, "errors:", errors)
            await ctx.close()
        await browser.close()

asyncio.run(main())


