            page.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
            page.on("pageerror", lambda e: errors.append(str(e)))
            await page.goto(HTML.as_uri(), wait_until="load")
            await page.screenshot(path=str(OUT / f"shot_{name}.png"))
            # overflow check
            over = await page.evaluate("document.documentElement.scrollWidth > document.documentElement.clientWidth")
            print(name, "hscroll:", over, "errors:", errors)
            await ctx.close()
        await browser.close()

asyncio.run(main())


