import asyncio, json, pathlib
from playwright.async_api import async_playwright

HTML = pathlib.Path("/tmp/accept-landing-page-parallel-v1-v0-1-1glnaih7/y10-quota-20261011/landing.html").resolve()
OUT = HTML.parent

JS = """
() => {
  const r = el => { const b = el.getBoundingClientRect(); return {top: b.top, bottom: b.bottom, left: b.left, right: b.right, w: b.width, h: b.height}; };
  const prices = [...document.querySelectorAll('.price')].map(p => ({text: p.textContent.trim(), box: r(p)}));
  const cta = r(document.querySelector('.cta'));
  const brand = r(document.querySelector('.brand'));
  const m = r(document.querySelector('main'));
  const vw = document.documentElement.clientWidth;
  const fs = [...document.querySelectorAll('main p, main span, main a')].map(e => parseFloat(getComputedStyle(e).fontSize));
  return {vw, prices, cta, brand, main: m, minFont: Math.min(...fs)};
}
"""

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch(args=["--no-sandbox"])
        for name, w, h in [("mobile", 320, 568), ("desktop", 1024, 768)]:
            ctx = await browser.new_context(viewport={"width": w, "height": h})
            page = await ctx.new_page()
            await page.goto(HTML.as_uri(), wait_until="load")
            data = await page.evaluate(JS)
            print(name, json.dumps(data, ensure_ascii=False, indent=1))
            await page.screenshot(path=str(OUT / f"shot_{name}2.png"))
            await ctx.close()
        await browser.close()

asyncio.run(main())


